// Represents an activity suggestion generated by the activity recommender.
class ActivitySuggestion {
  constructor(title, description, type, categoryId = null) {
    if (!title || !description) {
      throw new Error('An activity suggestion requires a title and description.');
    }

    this.title = title;
    this.description = description;
    // 'indoor', 'outdoor', or 'general'
    this.type = type || 'general';
    // Optional category ID matching PlaceCategoryCatalog (e.g. 'museums', 'parks')
    this.categoryId = categoryId;
  }
}

// Result container returned by ActivityRecommender.
// Keeps suggestions and fallback messaging cleanly encapsulated.
class RecommendationResult {
  constructor(destinationName, weatherSummary, suggestions = [], fallbackMessage = '') {
    this.destinationName = destinationName;
    this.weatherSummary = weatherSummary;
    this.suggestions = suggestions;
    this.fallbackMessage = fallbackMessage;
  }

  hasSuggestions() {
    return this.suggestions.length > 0;
  }
}

// ActivityRecommender analyzes both the selected country/region and current weather
// conditions using clear JavaScript control structures (switch and if...else)
// to generate relevant travel activity suggestions.
class ActivityRecommender {
  constructor() {
    // Weather condition thresholds
    this.rainyWeatherCodes = new Set([
      51, 53, 55, 56, 57, 61, 63, 65, 66, 67, 80, 81, 82, 95, 96, 99
    ]);
    this.snowyWeatherCodes = new Set([71, 73, 75, 77, 85, 86]);
    this.foggyWeatherCodes = new Set([45, 48]);
  }

  // Primary method to evaluate country and weather conditions.
  recommend(destination, country, weather) {
    if (!destination) {
      return new RecommendationResult(
        '',
        '',
        [],
        'Select a destination to view tailored activity recommendations.'
      );
    }

    const destinationName = destination.getDisplayName();

    // If weather data is not available yet or failed to load
    if (!weather) {
      return new RecommendationResult(
        destinationName,
        'Weather information unavailable',
        [],
        'Weather conditions are currently unavailable to generate personalized activity recommendations.'
      );
    }

    const weatherSummary = `${weather.getDescription()} (${weather.getTemperatureLabel()})`;
    const weatherCategory = this.determineWeatherCategory(weather);
    const countryCode = (country && country.alpha2Code
      ? country.alpha2Code
      : destination.countryCode || ''
    ).toUpperCase();
    const region = country && country.region ? country.region : '';

    const suggestions = [];

    // 1. Weather-based recommendation logic using switch statement
    switch (weatherCategory) {
      case 'rainy_or_stormy':
        suggestions.push(
          new ActivitySuggestion(
            'Explore Local Museums & Art Galleries',
            'Heavy rain or showers detected. Staying indoors while discovering local history, art, and cultural heritage is ideal today.',
            'indoor',
            'museums'
          ),
          new ActivitySuggestion(
            'Indoor Shopping & Dining',
            'Visit indoor shopping centers and covered food markets to enjoy local specialties comfortably sheltered from the rain.',
            'indoor',
            'shopping'
          )
        );
        break;

      case 'snowy':
        suggestions.push(
          new ActivitySuggestion(
            'Winter Sightseeing & Snow Activities',
            'Snow is falling! Great for scenic winter photography, winter sports, or visiting historic landmarks dressed in snow.',
            'outdoor',
            'sights'
          ),
          new ActivitySuggestion(
            'Warm Cozy Cafes & Hearty Cuisine',
            'After being outdoors in the cold, warm up with hot beverages and traditional comfort foods at local cafes.',
            'indoor',
            'food'
          )
        );
        break;

      case 'hot_and_clear':
        suggestions.push(
          new ActivitySuggestion(
            'Early Morning or Late Afternoon Parks & Sights',
            'High temperatures detected. Explore outdoor landmarks and botanical gardens during cooler morning or late afternoon hours.',
            'outdoor',
            'parks'
          ),
          new ActivitySuggestion(
            'Air-Conditioned Attractions & Culinary Stops',
            'Beat the midday heat by checking out indoor attractions, galleries, and refreshing cafe stops.',
            'indoor',
            'attractions'
          )
        );
        break;

      case 'pleasant_and_clear':
        suggestions.push(
          new ActivitySuggestion(
            'Outdoor Walking Tour & Scenic Landmarks',
            'Clear skies and comfortable temperatures create ideal conditions for walking tours, architectural sights, and photo opportunities.',
            'outdoor',
            'sights'
          ),
          new ActivitySuggestion(
            'Parks, Nature Reserves & Waterfronts',
            'Take full advantage of the pleasant weather by visiting open-air nature parks, public gardens, or waterfront promenades.',
            'outdoor',
            'parks'
          )
        );
        break;

      case 'foggy':
        suggestions.push(
          new ActivitySuggestion(
            'Historic Quarter Walk & Atmospheric Photography',
            'Fog creates a unique, atmospheric backdrop for exploring historic streets, old town plazas, and temples or monuments.',
            'outdoor',
            'sights'
          ),
          new ActivitySuggestion(
            'Cultural Centers & Exhibitions',
            'Visibility might be limited for high viewpoints, making cultural centers and indoor exhibits a rewarding choice.',
            'indoor',
            'museums'
          )
        );
        break;

      default:
        // Mild / overcast conditions
        suggestions.push(
          new ActivitySuggestion(
            'City Highlights & Landmark Exploration',
            'Overcast but dry conditions are very comfortable for exploring city attractions and architectural landmarks on foot.',
            'general',
            'highlights'
          )
        );
        break;
    }

    // 2. Country and regional custom recommendation logic using if...else statements
    if (countryCode === 'MY' || countryCode === 'SG') {
      // Tropical Southeast Asian destinations (Malaysia / Singapore)
      if (weatherCategory === 'rainy_or_stormy' || weather.temperature >= 32) {
        suggestions.push(
          new ActivitySuggestion(
            'Explore Hawker Centers & Air-Conditioned Megamalls',
            'In tropical climates, covered hawker centers and air-conditioned shopping malls offer world-class food and relief from the tropical heat or downpours.',
            'indoor',
            'food'
          )
        );
      } else {
        suggestions.push(
          new ActivitySuggestion(
            'Visit Heritage Streets & Night Markets',
            'Take a walking tour of historic colonial quarters, vibrant street art, and evening pasar malam (night markets).',
            'outdoor',
            'sights'
          )
        );
      }
    } else if (countryCode === 'JP' || countryCode === 'KR') {
      // East Asian destinations (Japan / South Korea)
      if (weatherCategory === 'snowy' || weather.temperature < 5) {
        suggestions.push(
          new ActivitySuggestion(
            'Relax at an Onsen/Jjimjilbang or Hot Noodle Spot',
            'Cold weather is the perfect season to experience traditional hot springs or bathhouses, followed by hot ramen or stew.',
            'indoor',
            'attractions'
          )
        );
      } else if (weatherCategory === 'pleasant_and_clear') {
        suggestions.push(
          new ActivitySuggestion(
            'Historic Shrines, Temples & Traditional Gardens',
            'Stroll through peaceful temple gardens, historic palace grounds, and scenic traditional neighborhoods in beautiful weather.',
            'outdoor',
            'sights'
          )
        );
      }
    } else if (countryCode === 'GB' || countryCode === 'FR' || countryCode === 'IT' || region === 'Europe') {
      // European destinations
      if (weatherCategory === 'rainy_or_stormy') {
        suggestions.push(
          new ActivitySuggestion(
            'World-Renowned Art Museums & Historic Cathedrals',
            'Spend rainy hours wandering renowned museums, historic churches, and covered passageways (passages couverts).',
            'indoor',
            'museums'
          )
        );
      } else {
        suggestions.push(
          new ActivitySuggestion(
            'Open-Air Piazza Strolls & Alfresco Cafe Culture',
            'Soak up the historic European ambiance with an outdoor walking tour of plazas, followed by alfresco cafe dining.',
            'outdoor',
            'sights'
          )
        );
      }
    } else if (countryCode === 'AU' || countryCode === 'NZ' || region === 'Oceania') {
      // Oceania destinations
      if (weatherCategory === 'pleasant_and_clear' || weatherCategory === 'hot_and_clear') {
        suggestions.push(
          new ActivitySuggestion(
            'Coastal Walks, Harbor Tours & Beachfront Sightseeing',
            'Sunny skies make it the prime time to enjoy coastal trails, public beaches, and outdoor harbor activities.',
            'outdoor',
            'parks'
          )
        );
      }
    }

    // 3. Fallback check: Provide appropriate message if no suggestions matched
    if (suggestions.length === 0) {
      return new RecommendationResult(
        destinationName,
        weatherSummary,
        [],
        'No specific recommendations available for current conditions. Please browse available place categories below.'
      );
    }

    return new RecommendationResult(
      destinationName,
      weatherSummary,
      suggestions,
      ''
    );
  }

  // Classify current weather based on WMO weather codes, temperature, and precipitation
  determineWeatherCategory(weather) {
    if (this.snowyWeatherCodes.has(weather.weatherCode)) {
      return 'snowy';
    }

    if (
      this.rainyWeatherCodes.has(weather.weatherCode) ||
      (typeof weather.precipitation === 'number' && weather.precipitation > 1.0)
    ) {
      return 'rainy_or_stormy';
    }

    if (this.foggyWeatherCodes.has(weather.weatherCode)) {
      return 'foggy';
    }

    // High temperature with dry conditions
    if (typeof weather.temperature === 'number' && weather.temperature >= 32) {
      return 'hot_and_clear';
    }

    // Comfortable mild weather with low cloud cover
    if (
      typeof weather.temperature === 'number' &&
      weather.temperature >= 16 &&
      weather.temperature < 32 &&
      (weather.weatherCode === 0 || weather.weatherCode === 1 || weather.weatherCode === 2)
    ) {
      return 'pleasant_and_clear';
    }

    return 'overcast_or_mild';
  }
}

module.exports = {
  ActivitySuggestion,
  RecommendationResult,
  ActivityRecommender,
};
